    if($a==='webhook'){
        $u=dec((string)file_get_contents('php://input'),[]);
        if(!empty($u['message']['text'])&&str_starts_with(trim((string)$u['message']['text']),'/start')){
            $parts=explode(' ',trim((string)$u['message']['text']),2);
            $start=$parts[1]??'';
            $cid=$u['message']['chat']['id']??0;
            $nm=$u['message']['from']['first_name']??'বন্ধু';
            $keyboard=['inline_keyboard'=>[[['text'=>'🚀 Open Mini App','web_app'=>['url'=>app_url().'?start='.rawurlencode($start)]]]]];
            tg('sendMessage',['chat_id'=>$cid,'text'=>'স্বাগতম '.$nm.'। নিচের বাটনে Mini App খুলুন।','reply_markup'=>json_encode($keyboard,JSON_UNESCAPED_UNICODE)]);
        }
        out(['ok'=>true]);
    }
    out(['ok'=>false,'error'=>'unknown_action'],404);
}

function head_html(string $title,string $kind='user'):string{$cfg=['name'=>APP_NAME,'version'=>APP_VERSION,'csrf'=>csrf(),'telegram'=>TELEGRAM_USERNAME,'monetag'=>MONETAG_ZONE_ID,'reward_url'=>MONETAG_REWARDED_URL];return '<!doctype html><html lang="bn"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#08080d"><meta name="csrf-token" content="'.h($cfg['csrf']).'"><link rel="manifest" href="?action=pwa_manifest"><title>'.h($title).'</title><style>'.css().'</style><script>window.CFG='.json_encode($cfg,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).';window.KIND='.json_encode($kind).';</script></head><body><div id="app"></div><div id="toast"></div>';}
function css():string{return <<<'CSS'
:root{--bg:#08080d;--card:#121219;--line:rgba(255,255,255,.08);--text:#f6f4ef;--muted:#8d8b95;--o:#ff713f;--o2:#ff934f;--g:#2bd7a6;--b:#39a8ff;--y:#ffc62b;--r:#ff5366;--p:#9f79ff}*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}html,body{margin:0;background:var(--bg);color:var(--text);font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}body:before{content:"";position:fixed;inset:0;pointer-events:none;opacity:.13;background-image:linear-gradient(rgba(255,255,255,.06) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.06) 1px,transparent 1px);background-size:44px 44px}button,input,select,textarea{font:inherit}button{cursor:pointer}.wrap{width:min(980px,100%);margin:auto;padding:18px 16px 110px}.top{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:10px 2px 18px}.brand{font-weight:950;font-size:21px;display:flex;gap:10px;align-items:center}.dot{width:10px;height:10px;border-radius:50%;background:var(--o);box-shadow:0 0 20px var(--o)}.hero,.card{background:linear-gradient(180deg,rgba(255,255,255,.045),rgba(255,255,255,.015));border:1px solid var(--line);border-radius:24px;box-shadow:0 12px 42px rgba(0,0,0,.22)}.hero{padding:20px;border-color:rgba(255,113,63,.22)}.card{padding:17px}.row{display:flex;align-items:center;gap:10px}.between{display:flex;justify-content:space-between;align-items:center;gap:10px}.grid2{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.grid4{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.muted{color:var(--muted)}.small{font-size:12px}.balance{font-size:42px;font-weight:950;letter-spacing:-1px}.btn{min-height:46px;padding:0 15px;border-radius:15px;border:1px solid var(--line);background:#14141b;color:#fff;font-weight:850}.btn.primary{background:linear-gradient(135deg,var(--o),var(--o2));box-shadow:0 10px 30px rgba(255,113,63,.22)}.btn.green{background:linear-gradient(135deg,#19b58e,#36d9ac)}.btn.blue{background:linear-gradient(135deg,#258edf,#4bbcff)}.btn.danger{background:linear-gradient(135deg,#df3852,#ff6578)}.full{width:100%}.input,.select,.area{width:100%;background:#0d0d13;color:#fff;border:1px solid var(--line);border-radius:14px;padding:12px;outline:0}.area{min-height:100px}.section{font-size:21px;font-weight:950;margin:20px 0 10px}.stat{padding:14px;border-radius:18px;background:#111118;border:1px solid var(--line)}.value{font-size:25px;font-weight:950}.task{display:flex;align-items:center;gap:12px;padding:14px;border:1px solid var(--line);background:rgba(255,255,255,.025);border-radius:20px;margin-top:10px}.taski{width:48px;height:48px;border-radius:14px;display:grid;place-items:center;background:rgba(255,113,63,.1);border:1px solid rgba(255,113,63,.2);font-weight:950;font-size:22px}.taskm{min-width:0;flex:1}.tt{font-weight:900;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.ts{display:flex;gap:8px;flex-wrap:wrap;color:var(--muted);font-size:12px;margin-top:5px}.badge{display:inline-flex;align-items:center;gap:6px;padding:6px 9px;border-radius:999px;background:rgba(255,255,255,.035);border:1px solid var(--line);font-size:12px}.orange{color:var(--o);border-color:rgba(255,113,63,.25)}.green{color:var(--g);border-color:rgba(43,215,166,.25)}.red{color:var(--r);border-color:rgba(255,83,102,.25)}.blue{color:var(--b);border-color:rgba(57,168,255,.25)}.progress{height:8px;background:#2a2426;border-radius:999px;overflow:hidden}.progress i{display:block;height:100%;background:linear-gradient(90deg,var(--o),var(--y));border-radius:999px}.nav{position:fixed;left:0;right:0;bottom:0;background:rgba(8,8,13,.93);backdrop-filter:blur(18px);border-top:1px solid var(--line);z-index:30;padding:8px 10px calc(8px + env(safe-area-inset-bottom))}.navin{width:min(760px,100%);margin:auto;display:grid;grid-template-columns:repeat(5,1fr);gap:6px}.ni{height:60px;border-radius:15px;color:#77757e;display:flex;flex-direction:column;align-items:center;justify-content:center;font-size:11px;font-weight:850}.ni.a{color:var(--o);background:rgba(255,113,63,.08)}.spin{width:min(76vw,320px);aspect-ratio:1;border-radius:50%;margin:10px auto 18px;border:8px solid rgba(255,255,255,.08);position:relative;overflow:hidden;box-shadow:0 0 60px rgba(255,113,63,.13)}.seg{position:absolute;inset:0;clip-path:polygon(50% 50%,0 0,100% 0);display:grid;place-items:start center;padding-top:20px;font-size:12px;font-weight:900}.center{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:68px;height:68px;border-radius:50%;background:#0f0f15;display:grid;place-items:center;border:3px solid rgba(255,255,255,.14);z-index:2}.rank{display:grid;grid-template-columns:36px 44px 1fr auto;gap:10px;align-items:center;padding:12px 0;border-bottom:1px solid var(--line)}.avatar{width:54px;height:54px;border-radius:17px;object-fit:cover;background:#17171e}.login{min-height:100vh;display:grid;place-items:center;padding:24px}.loginbox{width:min(430px,100%);padding:26px;border:1px solid var(--line);background:#101017;border-radius:26px}.admin{width:min(1500px,100%);margin:auto;padding:15px}.admgrid{display:grid;grid-template-columns:235px 1fr;gap:14px}.side{background:#101017;border:1px solid var(--line);border-radius:22px;padding:12px;min-height:calc(100vh - 30px);position:sticky;top:15px}.sidebtn{padding:12px;border-radius:12px;color:var(--muted);font-weight:850;margin-top:4px}.sidebtn.a,.sidebtn:hover{background:rgba(255,113,63,.08);color:var(--o)}.table{overflow:auto;border:1px solid var(--line);border-radius:18px}.table table{width:100%;min-width:850px;border-collapse:collapse}.table th,.table td{padding:11px;border-bottom:1px solid var(--line);font-size:13px;text-align:left}.toast{position:fixed;top:15px;right:15px;z-index:100;background:#17171f;border:1px solid var(--line);border-radius:14px;padding:12px 15px;box-shadow:0 15px 45px rgba(0,0,0,.35)}.modal{position:fixed;inset:0;background:rgba(0,0,0,.65);display:none;align-items:flex-end;z-index:80}.modal.show{display:flex}.sheet{width:min(760px,100%);margin:auto 0 0;padding:18px 16px calc(18px + env(safe-area-inset-bottom));background:#101016;border:1px solid var(--line);border-radius:26px 26px 0 0;max-height:90vh;overflow:auto}.empty{text-align:center;padding:30px;color:var(--muted);border:1px dashed var(--line);border-radius:18px}@media(max-width:850px){.admgrid{grid-template-columns:1fr}.side{position:relative;min-height:auto}.grid4{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.grid2{grid-template-columns:1fr}.grid4{grid-template-columns:repeat(2,1fr)}.wrap{padding-left:13px;padding-right:13px}.balance{font-size:36px}}
CSS;}

function js_common(){return <<<'JS'
const $=(s,p=document)=>p.querySelector(s),$$=(s,p=document)=>Array.from(p.querySelectorAll(s));
function esc(x){return String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function num(x,d=0){let n=Number(x);return Number.isFinite(n)?n:d}
function money(x){return num(x).toFixed(3).replace(/\.?0+$/,'')}
function toast(x){const d=document.createElement('div');d.className='toast';d.textContent=x;document.body.appendChild(d);setTimeout(()=>d.remove(),3500)}
function modal(x){let m=$('#modal');if(!m){m=document.createElement('div');m.id='modal';m.className='modal';m.innerHTML='<div class="sheet" id="sheet"></div>';document.body.appendChild(m);m.addEventListener('click',e=>{if(e.target===m)m.classList.remove('show')})}$('#sheet').innerHTML=x;m.classList.add('show')}
function closeModal(){$('#modal')?.classList.remove('show')}
async function api(a,d={},o={}){let opt={method:o.method||'POST',headers:{'X-Requested-With':'XMLHttpRequest'}};if(opt.method==='GET'){let q=new URLSearchParams(d);return fetch('?action='+encodeURIComponent(a)+'&'+q.toString(),opt).then(r=>r.json())}if(o.form){opt.body=d}else{opt.headers['Content-Type']='application/json';opt.body=JSON.stringify({...d,csrf:CFG.csrf})}const r=await fetch('?action='+encodeURIComponent(a),opt);let j;try{j=await r.json()}catch(e){throw Error('Invalid server response')}if(!j.ok&&o.throw!==false)throw Error(j.error||'Request failed');return j}
function nav(active){const a=[['home','⌂','হোম'],['tasks','◎','টাস্ক'],['rank','🏆','র‍্যাঙ্ক'],['activity','▣','কার্যক্রম'],['profile','♙','প্রোফাইল']];return '<div class="nav"><div class="navin">'+a.map(x=>'<div class="ni '+(x[0]===active?'a':'')+'" data-nav="'+x[0]+'"><div style="font-size:22px">'+x[1]+'</div><div>'+x[2]+'</div></div>').join('')+'</div>'}
function tgReady(){try{Telegram.WebApp.ready();Telegram.WebApp.expand();return true}catch(e){return false}}
JS;}

function userScript(){return <<<'JS'
const USER_APP=true;
let U=null,S={tab:'home',b:null};
function avatar(u=U){return u?.photo_url?'<img class="avatar" src="'+esc(u.photo_url)+'">':'<div class="avatar" style="display:grid;place-items:center;font-weight:950">'+esc((u?.name||'U').slice(0,1).toUpperCase())+'</div>'}
function taskList(ts){return ts.length?ts.map(t=>'<div class="task"><div class="taski">'+(t.category==='facebook'?'f':t.category==='youtube'?'▶':t.category==='tiktok'?'♪':t.category==='telegram'?'✈':'🌐')+'</div><div class="taskm"><div class="tt">'+esc(t.title)+'</div><div class="ts"><span>+'+money(t.reward)+' USDT</span><span>+'+num(t.xp,20)+' XP</span><span>'+num(t.completed_count)+'/'+(num(t.max_limit)||'∞')+'</span></div></div><button class="btn '+(t.user_completed?'green':'primary')+'" '+(t.user_completed?'disabled':'')+' onclick="openTask(\''+esc(t.id)+'\')">'+(t.user_completed?'✓':'শুরু করুন')+'</button></div>').join(''):'<div class="empty">কোনো task নেই</div>'}
function home(){let r=S.b,l=r.level||{},a=r.ads||{},st=r.streak||{},sp=r.spin||{};return '<div class="wrap"><div class="top"><div class="brand"><i class="dot"></i>'+esc(CFG.name)+'</div><div><button class="btn" onclick="sync()">↻</button></div></div><div class="hero"><div class="between"><div><div class="small muted">বর্তমান ব্যালেন্স</div><div class="balance">'+money(U.balance)+' <span style="font-size:17px;color:var(--g)">USDT</span></div></div>'+avatar()+'</div><div class="row" style="margin-top:12px"><span class="badge orange">Lv.'+num(l.current?.level,1)+'</span><span class="badge">'+esc(l.current?.badge||'Rookie')+'</span><span class="badge">XP '+num(U.xp)+'</span></div><div class="progress" style="margin-top:9px"><i style="width:'+num(l.progress)+'%"></i></div></div><div class="grid4" style="margin-top:10px"><div class="stat"><div class="value" style="color:var(--g)">'+money(U.balance)+'</div><div class="small muted">USDT</div></div><div class="stat"><div class="value" style="color:var(--y)">'+num(U.xp)+'</div><div class="small muted">FG XP</div></div><div class="stat"><div class="value" style="color:var(--o)">'+num(U.tasks_completed)+'</div><div class="small muted">সম্পন্ন</div></div><div class="stat"><div class="value" style="color:var(--p)">'+num(U.valid_referral_count)+'</div><div class="small muted">Valid Ref</div></div></div><div class="section">দৈনিক চেক-ইন</div><div class="card"><div class="between"><div><b>'+num(st.days)+' দিন</b><div class="small muted">আজকের streak reward</div></div><button class="btn primary" '+(st.claimed?'disabled':'')+' onclick="streak()">'+(st.claimed?'✓ Claim করা':'Claim')+'</button></div></div><div class="section">ডেইলি স্পিন</div><div class="card"><div class="spin" id="wheel">'+(S.b.settings.spin_slots||[]).slice(0,6).map((x,i)=>'<div class="seg" style="transform:rotate('+(i*60)+'deg);background:'+(i%2?'#24191b':'#181820')+'"><span>'+esc(x.label||'')+'</span></div>').join('')+'<div class="center">'+(sp.ready?'SPIN':'24H')+'</div></div><button class="btn primary full" '+(sp.ready?'':'disabled')+' onclick="spin()">'+(sp.ready?'🎡 SPIN NOW':'Cooldown')+'</button></div><div class="section">জনপ্রিয় টাস্ক</div><div id="ht">'+taskList((S.b.tasks||[]).slice(0,4))+'</div><div class="section">Ads</div><div class="card"><div class="between"><div><b>Daily Ads</b><div class="small muted">'+num(a.count)+'/'+num(a.limit)+'</div></div><button class="btn blue" onclick="watchAd()">দেখুন</button></div></div>'+nav('home')+'</div>'}
function tasks(){let ts=S.b.tasks||[];return '<div class="wrap"><div class="top"><div><div class="small muted">আপনার জন্য</div><h1 style="margin:4px 0">টাস্ক সেন্টার</h1></div><button class="btn" onclick="sync()">↻</button></div><div class="row" style="overflow:auto">'+[['','সব'],['youtube','YouTube'],['facebook','Facebook'],['tiktok','TikTok'],['telegram','Telegram'],['website','Website'],['ad','Ads']].map(x=>'<button class="badge" onclick="filterTask(\''+x[0]+'\')">'+x[1]+'</button>').join('')+'</div><div class="section">Available</div><div id="tl">'+taskList(ts)+'</div>'+nav('tasks')+'</div>'}
function ranks(){return '<div class="wrap"><div class="top"><div><div class="small muted">কমিউনিটি</div><h1 style="margin:4px 0">লিডারবোর্ড</h1></div></div><div class="card"><div class="between"><div class="small muted">আমার ব্যালেন্স</div><strong>'+money(U.balance)+' USDT</strong></div></div><div class="section">Top Users</div><div class="card">'+(S.b.leaders||[]).map((x,i)=>'<div class="rank"><b>#'+(i+1)+'</b>'+avatar(x)+'<div><b>'+esc(x.name)+'</b><div class="small muted">'+num(x.tasks_completed)+' tasks • Lv.'+num(x.level?.level,1)+'</div></div><strong style="color:var(--y)">'+money(x.balance)+'</strong></div>').join('')+'</div>'+nav('rank')+'</div>'}
function activity(){return '<div class="wrap"><div class="top"><div><div class="small muted">লেনদেন</div><h1 style="margin:4px 0">কার্যক্রম</h1></div><button class="btn primary" onclick="withdrawForm()">উত্তোলন</button></div><div class="card">'+((S.b.withdrawals||[]).length?(S.b.withdrawals||[]).map(w=>'<div style="padding:12px 0;border-bottom:1px solid var(--line)"><div class="between"><b>'+money(w.amount)+' USDT</b><span class="badge '+(w.status==='approved'?'green':w.status==='rejected'?'red':'orange')+'">'+esc(w.status)+'</span></div><div class="small muted">'+esc(w.method)+' • '+esc(w.account)+'</div></div>').join(''):'<div class="empty">কোনো withdrawal নেই</div>')+'</div>'+nav('activity')+'</div>'}
function profile(){let l=S.b.level;return '<div class="wrap"><div class="top"><div><div class="small muted">আপনার অ্যাকাউন্ট</div><h1 style="margin:4px 0">প্রোফাইল</h1></div></div><div class="card"><div class="row">'+avatar()+'<div style="flex:1"><b style="font-size:21px">'+esc(U.name)+'</b><div class="small muted">ID: '+esc(U.telegram_id)+'</div><div class="row" style="margin-top:6px"><span class="badge orange">Lv.'+num(l.current?.level,1)+'</span><span class="badge">'+esc(l.current?.badge||'Rookie')+'</span></div></div><span class="badge">Fraud '+num(U.fraud_score)+'</span></div><div class="progress" style="margin-top:10px"><i style="width:'+num(l.progress)+'%"></i></div></div><div class="section">আমার ওয়ালেট</div><div class="card"><div class="balance" style="font-size:37px">'+money(U.balance)+' <span style="font-size:16px;color:var(--g)">USDT</span></div><button class="btn primary full" onclick="withdrawForm()">উত্তোলন</button></div><div class="section">Referral</div><div class="card"><div class="between"><div><b>'+num(U.valid_referral_count)+' Valid</b><div class="small muted">প্রথম approved withdrawal-এর পরে valid</div></div><button class="btn" onclick="copyRef()">কপি</button></div><div class="input" style="margin-top:10px">https://t.me/'+esc(CFG.telegram)+'?start=ref_'+esc(U.telegram_id)+'</div></div>'+nav('profile')+'</div>'}
function render(){let v={home,tasks,rank:ranks,activity,profile};$('#app').innerHTML=v[S.tab]();$$('[data-nav]').forEach(x=>x.onclick=()=>{S.tab=x.dataset.nav;render()})}
async function sync(){try{S.b=await api('bootstrap');U=S.b.user;render()}catch(e){toast(e.message)}}
async function startUser(){if(!tgReady()){ $('#app').innerHTML='<div class="login"><div class="loginbox"><div class="brand"><i class="dot"></i>'+esc(CFG.name)+'</div><h2>Telegram Mini App</h2><p class="muted">এই অ্যাপটি Telegram-এর ভিতর থেকে খুলুন।</p></div></div>';return}try{let x=await api('init',{initData:Telegram.WebApp.initData,start_param:Telegram.WebApp.initDataUnsafe?.start_param||''});U=x.user;if(!x.join.ok){$('#app').innerHTML='<div class="login"><div class="loginbox"><div class="brand"><i class="dot"></i>'+esc(CFG.name)+'</div><h2>Join required</h2><p class="muted">প্রথমে required channel/group join করুন।</p><div class="card">'+(x.join.missing||[]).map(v=>'<div style="padding:8px 0;border-bottom:1px solid var(--line)">'+esc(v)+'</div>').join('')+'</div><button class="btn primary full" style="margin-top:10px" onclick="startUser()">আমি Join করেছি</button></div></div>';return}S.b=await api('bootstrap');render()}catch(e){$('#app').innerHTML='<div class="login"><div class="loginbox"><h2>Authentication Error</h2><p class="muted">'+esc(e.message)+'</p><button class="btn primary full" onclick="location.reload()">Reload</button></div></div>'}}
function openTask(id){api('task_open',{task_id:id}).then(r=>{let t=r.task;modal('<div class="between"><h2>'+esc(t.title)+'</h2><button class="btn" onclick="closeModal()">×</button></div><p class="muted">'+esc(t.description||'')+'</p><div class="card"><div class="between"><span>Reward</span><b style="color:var(--g)">+'+money(t.reward)+' USDT</b></div></div><a class="btn blue full" href="'+esc(t.link)+'" target="_blank" rel="noopener">লিংক খুলুন</a>'+(t.require_screenshot||t.require_profile_link||t.require_review?'<form id="pf" style="margin-top:12px"><input type="hidden" name="task_id" value="'+esc(id)+'">'+(t.require_profile_link?'<input class="input" name="profile_link" placeholder="Profile link" required>':'')+(t.require_screenshot?'<input class="input" type="file" name="proof" accept="image/png,image/jpeg,image/webp" style="margin-top:9px" required>':'')+'<button class="btn primary full" style="margin-top:10px">Submit Proof</button></form>':'<button class="btn primary full" style="margin-top:10px" onclick="finish(\''+esc(id)+'\')">কাজ শেষ করেছি</button>'));$('#pf')?.addEventListener('submit',async e=>{e.preventDefault();try{let r=await api('task_submit',new FormData(e.currentTarget),{form:true,throw:false});if(!r.ok)throw Error(r.error);closeModal();toast(r.status==='pending'?'Proof submitted':'Task completed');await sync()}catch(er){toast(er.message)}})}).catch(e=>toast(e.message))}
async function finish(id){try{let r=await api('task_submit',new URLSearchParams({task_id:id}),{form:true,throw:false});if(!r.ok)throw Error(r.error);closeModal();toast('Task completed');await sync()}catch(e){toast(e.message)}}
async function filterTask(cat){let r=await api('tasks',{category:cat},{method:'GET'});if(r.ok)$('#tl').innerHTML=taskList(r.tasks||[])}
async function spin(){try{let r=await api('spin',{});let w=$('#wheel');if(w)w.style.transform='rotate('+(1440+num(r.index)*60+30)+'deg)';await new Promise(q=>setTimeout(q,4300));toast((r.slot?.label||'Reward')+' পাওয়া গেছে');await sync()}catch(e){toast(e.message)}}
async function streak(){try{let r=await api('streak',{});toast('+'+money(r.reward)+' USDT');await sync()}catch(e){toast(e.message)}}
async function watchAd(){try{if(CFG.reward_url)window.open(CFG.reward_url,'_blank');let r=await api('ad_view',{});if(r.ok)toast('Ad recorded');await sync()}catch(e){toast(e.message)}}
function copyRef(){let x='https://t.me/'+CFG.telegram+'?start=ref_'+U.telegram_id;navigator.clipboard?.writeText(x).then(()=>toast('কপি হয়েছে')).catch(()=>toast(x))}
function withdrawForm(){let min=num(S.b.settings?.min_withdraw,1);modal('<div class="between"><h2>উত্তোলন</h2><button class="btn" onclick="closeModal()">×</button></div><form id="wf"><input class="input" name="amount" type="number" step="0.001" min="'+min+'" placeholder="Amount" required><select class="select" name="method" style="margin-top:9px"><option value="binance">Binance</option><option value="bkash">bKash</option><option value="nagad">Nagad</option><option value="rocket">Rocket</option></select><input class="input" name="account" placeholder="UID / Number" style="margin-top:9px" required><button class="btn primary full" style="margin-top:10px">Request</button></form>');$('#wf').addEventListener('submit',async e=>{e.preventDefault();try{await api('withdraw',Object.fromEntries(new FormData(e.currentTarget)));closeModal();toast('Request submitted');await sync()}catch(er){toast(er.message)}})}
JS;}

function adminScript(){return <<<'JS'
let A={tab:'dashboard',d:null};
function adminLogin(){return '<div class="login"><div class="loginbox"><div class="brand"><i class="dot"></i>'+esc(CFG.name)+' Admin</div><h1>Admin Dashboard</h1><form id="al"><input class="input" type="password" name="password" placeholder="Admin password" required><button class="btn primary full" style="margin-top:10px">Login</button></form></div></div>'}
function side(){let it=[['dashboard','◈','Dashboard'],['tasks','◎','Tasks'],['proofs','▣','Proofs'],['withdrawals','↯','Withdrawals'],['users','♙','Users'],['managers','♚','Managers'],['campaigns','✦','Campaigns'],['settings','⚙','Settings'],['logs','◌','Logs'],['backup','⤓','Backup']];return'<aside class="side"><div class="brand" style="padding:8px"><i class="dot"></i>'+esc(CFG.name)+'</div>'+it.map(x=>'<div class="sidebtn '+(A.tab===x[0]?'a':'')+'" data-tab="'+x[0]+'">'+x[1]+' '+x[2]+'</div>').join('')+'<div style="margin-top:20px"><button class="btn full" onclick="logout()">Logout</button></div></aside>'}
function adminView(){let s=A.d?.stats||{};if(A.tab==='dashboard')return'<div class="grid4"><div class="card"><div class="muted small">Users</div><div class="value">'+num(s.users)+'</div></div><div class="card"><div class="muted small">Tasks</div><div class="value">'+num(s.tasks)+'</div></div><div class="card"><div class="muted small">Proofs</div><div class="value" style="color:var(--y)">'+num(s.proofs)+'</div></div><div class="card"><div class="muted small">Withdrawals</div><div class="value" style="color:var(--o)">'+num(s.withdrawals)+'</div></div></div><div class="grid2" style="margin-top:12px"><div class="card"><div class="between"><b>Manager Load</b><span class="badge orange">Auto</span></div>'+Object.entries(A.d.managers||{}).map(([id,m])=>'<div style="margin-top:10px"><div class="between"><span>'+esc(m.name||id)+'</span><b>'+A.d.withdrawals?Object.values(A.d.withdrawals).filter(x=>x.manager_id===id&&x.status==='pending').length:0+'/'+num(m.max_open,10)+'</b></div><div class="progress" style="margin-top:6px"><i style="width:30%"></i></div></div>').join('')+'</div><div class="card"><div class="between"><b>Quick Actions</b><button class="btn primary" onclick="newTask()">+ Task</button></div><div class="row" style="margin-top:10px"><button class="btn" onclick="A.tab='settings';renderAdmin()">Settings</button><button class="btn" onclick="A.tab='backup';renderAdmin()">Backup</button></div></div></div>';
if(A.tab==='tasks')return tasksPanel();
if(A.tab==='proofs')return proofPanel();
if(A.tab==='withdrawals')return withdrawPanel();
if(A.tab==='users')return usersPanel();
if(A.tab==='managers')return managersPanel();
if(A.tab==='campaigns')return campaignsPanel();
if(A.tab==='settings')return settingsPanel();
if(A.tab==='logs')return logsPanel();
return backupPanel();}
function tasksPanel(){let t=A.d.tasks||{};return'<div class="between"><button class="btn primary" onclick="newTask()">+ Add Task</button><div class="row"><a class="btn" href="?action=export_users">Users CSV</a><a class="btn" href="?action=export_withdrawals">Withdrawals CSV</a></div></div><div class="table" style="margin-top:10px"><table><thead><tr><th>Title</th><th>Reward</th><th>Limit</th><th>Schedule</th><th>Manager</th><th>State</th><th>Action</th></tr></thead><tbody>'+Object.entries(t).map(([id,x])=>'<tr><td><b>'+esc(x.title)+'</b><div class="small muted">'+esc(x.category)+'</div></td><td>'+money(x.reward)+'</td><td>'+num(x.completed_count)+'/'+(num(x.max_limit)||'∞')+'</td><td>'+((x.publish_at_ts?new Date(x.publish_at_ts*1000).toLocaleString():'Now'))+'<br>'+((x.expires_at_ts?new Date(x.expires_at_ts*1000).toLocaleString():'No expiry'))+'</td><td>'+esc(A.d.managers?.[x.manager_id]?.name||x.manager_id||'Auto')+'</td><td><span class="badge '+(x.disabled?'red':'green')+'">'+(x.disabled?'Off':'Live')+'</span></td><td><button class="btn" onclick="editTask('+JSON.stringify(x).replace(/</g,'\\u003c')+')">Edit</button></td></tr>').join('')+'</tbody></table></div>'}
function taskForm(t={}){modal('<div class="between"><h2>'+(t.id?'Edit':'New')+' Task</h2><button class="btn" onclick="closeModal()">×</button></div><form id="tf"><input type="hidden" name="id" value="'+esc(t.id||'')+'"><input class="input" name="title" placeholder="Title" value="'+esc(t.title||'')+'" required><textarea class="area" name="description" placeholder="Description" style="margin-top:9px">'+esc(t.description||'')+'</textarea><input class="input" name="link" placeholder="Task URL" value="'+esc(t.link||'')+'" style="margin-top:9px" required><div class="grid2" style="margin-top:9px"><input class="input" name="reward" type="number" step="0.001" value="'+num(t.reward)+'" placeholder="Reward"><input class="input" name="xp" value="'+num(t.xp,20)+'" placeholder="XP"></div><div class="grid2" style="margin-top:9px"><input class="input" name="max_limit" type="number" value="'+num(t.max_limit)+'" placeholder="Max users"><input class="input" name="priority" type="number" value="'+num(t.priority)+'" placeholder="Priority"></div><div class="grid2" style="margin-top:9px"><select class="select" name="category">'+['youtube','facebook','tiktok','telegram','website','ad'].map(x=>'<option '+(t.category===x?'selected':'')+' value="'+x+'">'+x+'</option>').join('')+'</select><select class="select" name="manager_id"><option value="">Auto-balancer</option>'+Object.entries(A.d.managers||{}).map(([id,m])=>'<option value="'+id+'" '+(t.manager_id===id?'selected':'')+'>'+esc(m.name||id)+'</option>').join('')+'</select></div><div class="grid2" style="margin-top:9px"><input class="input" name="publish_at" type="datetime-local" value="'+dateInput(t.publish_at_ts)+'"><input class="input" name="expires_at" type="datetime-local" value="'+dateInput(t.expires_at_ts)+'"></div><div class="row" style="flex-wrap:wrap;margin-top:10px"><label class="badge"><input type="checkbox" name="require_screenshot" '+(t.require_screenshot?'checked':'')+'> Screenshot</label><label class="badge"><input type="checkbox" name="require_profile_link" '+(t.require_profile_link?'checked':'')+'> Profile</label><label class="badge"><input type="checkbox" name="require_review" '+(t.require_review?'checked':'')+'> Review</label><label class="badge"><input type="checkbox" name="disabled" '+(t.disabled?'checked':'')+'> Disabled</label></div><button class="btn primary full" style="margin-top:12px">Save Task</button></form>');$('#tf').addEventListener('submit',async e=>{e.preventDefault();let fd=new FormData(e.currentTarget),d=Object.fromEntries(fd.entries());d.require_screenshot=fd.has('require_screenshot');d.require_profile_link=fd.has('require_profile_link');d.require_review=fd.has('require_review');d.disabled=fd.has('disabled');d.publish_at_ts=d.publish_at?Math.floor(new Date(d.publish_at).getTime()/1000):0;d.expires_at_ts=d.expires_at?Math.floor(new Date(d.expires_at).getTime()/1000):0;delete d.publish_at;delete d.expires_at;try{await api('task_save',d);closeModal();toast('Task saved');loadAdmin()}catch(er){toast(er.message)}})}
function dateInput(x){if(!x)return'';let d=new Date(x*1000),p=n=>String(n).padStart(2,'0');return d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate())+'T'+p(d.getHours())+':'+p(d.getMinutes())}
function newTask(){taskForm({})}function editTask(t){taskForm(t)}
function proofPanel(){let x=Object.entries(A.d.submissions||{}).filter(([id,v])=>v.status==='pending');return'<div class="card"><b>Proof Queue ('+x.length+')</b></div>'+x.map(([id,v])=>'<div class="card" style="margin-top:9px"><div class="between"><div><b>'+esc(v.id)+'</b><div class="small muted">User '+esc(v.telegram_id)+' • Fraud '+num(v.fraud_score)+'</div></div><span class="badge orange">'+esc(v.manager_id||'Auto')+'</span></div><div class="row" style="margin-top:9px">'+(v.proof_file?'<a class="btn blue" href="?proof='+encodeURIComponent(v.proof_file)+'" target="_blank">Proof</a>':'')+'<button class="btn green" onclick="review(\'submission_review\',\''+esc(id)+'\',\'approved\')">Approve</button><button class="btn danger" onclick="review(\'submission_review\',\''+esc(id)+'\',\'rejected\')">Reject</button></div></div>').join('')}
function withdrawPanel(){let x=Object.entries(A.d.withdrawals||{}).filter(([id,v])=>v.status==='pending');return'<div class="card"><b>Withdrawal Queue ('+x.length+')</b></div>'+x.map(([id,v])=>'<div class="card" style="margin-top:9px"><div class="between"><b>'+money(v.amount)+' USDT</b><span class="badge">'+esc(v.method)+'</span></div><div class="small muted">'+esc(v.telegram_id)+' • '+esc(v.account)+' • Fraud '+num(v.fraud_score)+'</div><div class="row" style="margin-top:9px"><button class="btn green" onclick="review(\'withdraw_review\',\''+esc(id)+'\',\'approved\')">Approve</button><button class="btn danger" onclick="review(\'withdraw_review\',\''+esc(id)+'\',\'rejected\')">Reject</button></div></div>').join('')}
function usersPanel(){let x=Object.entries(A.d.users||{});return'<div class="card"><div class="between"><b>Users</b><a class="btn" href="?action=export_users">CSV</a></div><input class="input" id="us" placeholder="Search" style="margin-top:10px"><div id="ut" style="margin-top:10px">'+userTable(x)+'</div></div>'}
function userTable(x){return'<div class="table"><table><thead><tr><th>User</th><th>Balance</th><th>XP</th><th>Tasks</th><th>Ref</th><th>Fraud</th><th>Status</th><th></th></tr></thead><tbody>'+x.map(([id,u])=>'<tr><td><b>'+esc(u.name||id)+'</b><div class="small muted">'+esc(u.username||'')+' / '+id+'</div></td><td>'+money(u.balance)+'</td><td>'+num(u.xp)+'</td><td>'+num(u.tasks_completed)+'</td><td>'+num(u.valid_referral_count)+'</td><td>'+num(u.fraud_score)+'</td><td>'+(!u.blocked&&!u.suspended?'Active':u.blocked?'Blocked':'Suspended')+'</td><td><button class="btn" onclick="userEdit(\''+id+'\')">Manage</button></td></tr>').join('')+'</tbody></table></div>'}
function userEdit(id){let u=A.d.users[id]||{};modal('<div class="between"><h2>'+esc(u.name||id)+'</h2><button class="btn" onclick="closeModal()">×</button></div><input class="input" id="bd" type="number" step="0.001" placeholder="Balance delta" style="margin-top:10px"><input class="input" id="xp" type="number" value="'+num(u.xp)+'" placeholder="XP" style="margin-top:9px"><div class="row" style="margin-top:9px"><label class="badge"><input type="checkbox" id="bl" '+(u.blocked?'checked':'')+'> Block</label><label class="badge"><input type="checkbox" id="su" '+(u.suspended?'checked':'')+'> Suspend</label></div><button class="btn primary full" style="margin-top:10px" onclick="saveUser(\''+id+'\')">Save</button>')}
async function saveUser(id){try{await api('user_update',{telegram_id:id,balance_delta:num($('#bd').value),xp:num($('#xp').value),blocked:$('#bl').checked,suspended:$('#su').checked});closeModal();toast('User updated');loadAdmin()}catch(e){toast(e.message)}}
function managersPanel(){return'<div class="between"><button class="btn primary" onclick="managerForm({})">+ Manager</button><span class="badge orange">Auto-balancer</span></div><div class="grid2" style="margin-top:10px">'+Object.entries(A.d.managers||{}).map(([id,m])=>'<div class="card"><div class="between"><b>'+esc(m.name||id)+'</b><span class="badge '+(m.active?'green':'red')+'">'+(m.active?'Active':'Off')+'</span></div><div class="small muted">'+esc(id)+' • '+num(m.max_open)+'</div><div class="row" style="margin-top:10px"><button class="btn" onclick="managerForm('+JSON.stringify(m).replace(/</g,'\\u003c')+')">Edit</button><button class="btn danger" onclick="removeManager(\''+id+'\')">Delete</button></div></div>').join('')+'</div>'}
function managerForm(m){modal('<div class="between"><h2>Manager</h2><button class="btn" onclick="closeModal()">×</button></div><form id="mf"><input type="hidden" name="id" value="'+esc(m.id||'')+'"><input class="input" name="name" value="'+esc(m.name||'')+'" placeholder="Name" required><input class="input" name="username" value="'+esc(m.username||'')+'" placeholder="Username" style="margin-top:9px"><input class="input" name="password" type="password" placeholder="Password" style="margin-top:9px"><input class="input" name="max_open" value="'+num(m.max_open,10)+'" type="number" style="margin-top:9px"><label class="badge" style="margin-top:9px"><input type="checkbox" name="active" '+(m.active===false?'':'checked')+'> Active</label><button class="btn primary full" style="margin-top:10px">Save</button></form>');$('#mf').addEventListener('submit',async e=>{e.preventDefault();let fd=new FormData(e.currentTarget),d=Object.fromEntries(fd.entries());d.active=fd.has('active');try{await api('manager_save',d);closeModal();loadAdmin();toast('Manager saved')}catch(er){toast(er.message)}})}
async function removeManager(id){if(!confirm('Delete manager?'))return;await api('manager_delete',{id});loadAdmin()}
function campaignsPanel(){return'<div class="between"><button class="btn primary" onclick="campaignForm({})">+ Campaign</button></div><div class="grid2" style="margin-top:10px">'+Object.values(A.d.campaigns||{}).map(c=>'<div class="card"><div class="between"><b>'+esc(c.title)+'</b><span class="badge '+(c.active?'green':'red')+'">'+(c.active?'Active':'Off')+'</span></div><div class="small muted">+'+money(c.reward)+' USDT • Level '+num(c.target_level)+'</div></div>').join('')+'</div>'}
function campaignForm(c){modal('<div class="between"><h2>Bonus Campaign</h2><button class="btn" onclick="closeModal()">×</button></div><form id="cf"><input class="input" name="title" placeholder="Title" value="'+esc(c.title||'')+'" required><input class="input" name="reward" type="number" step="0.001" value="'+num(c.reward)+'" style="margin-top:9px"><input class="input" name="target_level" type="number" value="'+num(c.target_level)+'" style="margin-top:9px"><label class="badge" style="margin-top:9px"><input type="checkbox" name="active" '+(c.active===false?'':'checked')+'> Active</label><button class="btn primary full" style="margin-top:10px">Save</button></form>');$('#cf').addEventListener('submit',async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.currentTarget).entries());d.active=new FormData(e.currentTarget).has('active');try{await api('campaign_save',d);closeModal();loadAdmin()}catch(er){toast(er.message)}})}
function settingsPanel(){let s=A.d.settings||{};return'<div class="grid2"><div class="card"><h3>Core</h3><label class="small muted">Min Withdraw</label><input id="mn" class="input" value="'+num(s.min_withdraw,1)+'" type="number" step="0.001"><label class="small muted" style="display:block;margin-top:9px">Daily Ads</label><input id="adl" class="input" value="'+num(s.daily_ad_limit,15)+'" type="number"><label class="small muted" style="display:block;margin-top:9px">Manager Max Open</label><input id="mmo" class="input" value="'+num(s.manager_max_open,10)+'" type="number"><label class="small muted" style="display:block;margin-top:9px">Required Chats</label><textarea id="rch" class="area">'+esc((s.required_chats||[]).join('\n'))+'</textarea></div><div class="card"><h3>Spin</h3>'+((s.spin_slots||[]).slice(0,6).map((x,i)=>'<div class="grid2" style="margin-top:8px"><input class="input sl" data-i="'+i+'" value="'+esc(x.label||'')+'"><input class="input sr" data-i="'+i+'" type="number" step="0.001" value="'+num(x.reward)+'"></div>').join(''))+'<h3 style="margin-top:18px">Referral</h3>'+((s.refs||[]).slice(0,10).map((x,i)=>'<div class="grid2" style="margin-top:8px"><input class="input rv" data-i="'+i+'" value="'+num(x.valid)+'" type="number"><input class="input rb" data-i="'+i+'" value="'+num(x.bonus)+'" type="number" step="0.001"></div>').join(''))+'</div></div><button class="btn primary full" style="margin-top:10px" onclick="saveSettings()">Save Settings</button>'}
async function saveSettings(){let slots=$$('.sl').map((x,i)=>({label:x.value,reward:num($$('.sr')[i].value)})),refs=$$('.rv').map((x,i)=>({valid:num(x.value),bonus:num($$('.rb')[i].value)})),ch=($('#rch').value||'').split(/\n|,/).map(x=>x.trim()).filter(Boolean);try{await api('settings_save',{min_withdraw:num($('#mn').value),daily_ad_limit:num($('#adl').value),manager_max_open:num($('#mmo').value),required_chats:ch,spin_slots:slots,refs});toast('Settings saved');loadAdmin()}catch(e){toast(e.message)}}
function logsPanel(){return'<div class="table"><table><thead><tr><th>Action</th><th>Target</th><th>Time</th><th>Manager</th></tr></thead><tbody>'+Object.values(A.d.activity||{}).map(x=>'<tr><td>'+esc(x.action)+'</td><td>'+esc(x.target)+'</td><td>'+esc(x.created_at||'')+'</td><td>'+esc(x.manager_id||'')+'</td></tr>').join('')+'</tbody></table></div>'}
function backupPanel(){return'<div class="grid2"><div class="card"><h3>Backup</h3><p class="muted">Database JSON snapshot</p><button class="btn primary" onclick="backup()">Create Backup</button></div><div class="card"><h3>Maintenance</h3><button class="btn danger" onclick="maint()">Toggle Maintenance</button></div></div>'}
async function review(action,id,status){let reason=status==='rejected'?prompt('Reason','Not valid')||'':'';if(status==='rejected'&&!reason)return;try{await api(action,{id,status,reason});toast('Saved');loadAdmin()}catch(e){toast(e.message)}}
async function backup(){try{let r=await api('backup',{});toast('Backup: '+r.file)}catch(e){toast(e.message)}}
async function maint(){try{await api('maintenance',{enabled:!A.d.meta?.maintenance});loadAdmin()}catch(e){toast(e.message)}}
async function logout(){await api('admin_logout',{});location.reload()}
async function loadAdmin(){try{A.d=await api('admin_bootstrap',{});renderAdmin()}catch(e){$('#app').innerHTML=adminLogin();$('#al').addEventListener('submit',async ev=>{ev.preventDefault();try{await api('admin_login',{password:new FormData(ev.currentTarget).get('password')});loadAdmin()}catch(er){toast(er.message)}})}}
function renderAdmin(){$('#app').innerHTML='<div class="admin"><div class="admgrid">'+side()+'<main><div class="top"><div><div class="small muted">Control Center</div><h2 style="margin:3px 0">'+A.tab+'</h2></div><button class="btn" onclick="loadAdmin()">↻</button></div>'+adminView()+'</main></div></div>';$$('[data-tab]').forEach(x=>x.onclick=()=>{A.tab=x.dataset.tab;renderAdmin()})}
function managerLogin(){return'<div class="login"><div class="loginbox"><div class="brand"><i class="dot"></i>'+esc(CFG.name)+' Manager</div><form id="ml"><input class="input" name="manager_id" placeholder="Manager ID" required><input class="input" name="password" placeholder="Password" type="password" style="margin-top:9px" required><button class="btn primary full" style="margin-top:10px">Login</button></form></div></div>'}
async function managerPage(){try{let d=await api('manager_bootstrap',{});$('#app').innerHTML='<div class="admin"><div class="top"><div><div class="brand"><i class="dot"></i>'+esc(CFG.name)+' Manager</div><div class="small muted">'+esc(d.manager?.name||'Manager')+' • Open '+num(d.open)+'</div></div><button class="btn" onclick="managerPage()">↻</button></div><div class="grid2"><div class="card"><div class="between"><b>Proof Queue</b><span class="badge orange">'+Object.keys(d.submissions||{}).length+'</span></div>'+Object.values(d.submissions||{}).filter(x=>x.status==='pending').map(x=>'<div style="padding:10px 0;border-bottom:1px solid var(--line)"><b>'+esc(x.id)+'</b><div class="small muted">'+esc(x.profile_link||'')+'</div><div class="row" style="margin-top:7px"><button class="btn green" onclick="review(\'submission_review\',\''+esc(x.id)+'\',\'approved\')">Approve</button><button class="btn danger" onclick="review(\'submission_review\',\''+esc(x.id)+'\',\'rejected\')">Reject</button></div></div>').join('')+'</div><div class="card"><div class="between"><b>Withdrawal Queue</b><span class="badge orange">'+Object.keys(d.withdrawals||{}).length+'</span></div>'+Object.values(d.withdrawals||{}).filter(x=>x.status==='pending').map(x=>'<div style="padding:10px 0;border-bottom:1px solid var(--line)"><b>'+money(x.amount)+' USDT</b><div class="small muted">'+esc(x.method)+' • '+esc(x.account)+'</div><div class="row" style="margin-top:7px"><button class="btn green" onclick="review(\'withdraw_review\',\''+esc(x.id)+'\',\'approved\')">Approve</button><button class="btn danger" onclick="review(\'withdraw_review\',\''+esc(x.id)+'\',\'rejected\')">Reject</button></div></div>').join('')+'</div></div></div>'}catch(e){$('#app').innerHTML=managerLogin();$('#ml').addEventListener('submit',async ev=>{ev.preventDefault();try{await api('manager_login',Object.fromEntries(new FormData(ev.currentTarget)));managerPage()}catch(er){toast(er.message)}})}}
JS;}

function static_action():void{$a=action();if($a==='pwa_manifest'){header('Content-Type: application/manifest+json');echo json_encode(['name'=>APP_NAME,'short_name'=>APP_NAME,'start_url'=>app_url(),'display'=>'standalone','background_color'=>'#08080d','theme_color'=>'#08080d']);exit;}if($a==='service_worker'){header('Content-Type: application/javascript');echo 'self.addEventListener("install",e=>self.skipWaiting());self.addEventListener("activate",e=>self.clients.claim());self.addEventListener("fetch",e=>{});';exit;}if(isset($_GET['proof'])){require_mgr();$f=basename((string)$_GET['proof']);$p=UPLOAD_DIR.'/'.$f;if(!is_file($p)){http_response_code(404);exit;}$m=(new finfo(FILEINFO_MIME_TYPE))->file($p)?:'application/octet-stream';header('Content-Type:'.$m);header('Content-Disposition:inline; filename="'.$f.'"');readfile($p);exit;}}
$__unused_css = <<<'CSS'
<style>
.u-p0{padding:0px}
.u-m0{margin:0px}
.u-mt0{margin-top:0px}
.u-mb0{margin-bottom:0px}
.u-gap0{gap:0px}
.u-p1{padding:1px}
.u-m1{margin:1px}
.u-mt1{margin-top:1px}
.u-mb1{margin-bottom:1px}
.u-gap1{gap:1px}
.u-p2{padding:2px}
